<?php
if(PHP_SAPI!=='cli'||!in_array('--apply',$argv,true))throw new RuntimeException('Explicit apply required');
$c=require '/srv/state/private/config.php';if(empty($c['local_test'])||!str_contains($c['dsn'],'host=127.0.0.1;dbname=el_test_destination_'))throw new RuntimeException('Dev only');
require_once '/srv/portal/app/BusinessPublicImporter.php';$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$rows=json_decode(file_get_contents('/srv/state/cierre-38-20261104/businesses-dev1-rnt-expansion.json'),true,512,JSON_THROW_ON_ERROR);if(count($rows)!==624)throw new RuntimeException('Unexpected count');
$find=$p->prepare('SELECT b.id,b.publication_status FROM businesses b JOIN destinations d ON d.id=b.destination_id JOIN business_translations t ON t.business_id=b.id AND t.locale=\'es\' WHERE d.slug=? AND LOWER(TRIM(t.display_name))=LOWER(TRIM(?))');$pub=$p->prepare('UPDATE businesses SET publication_status=\'published\' WHERE id=? AND record_origin=\'public_import\'');$sub=$p->prepare('UPDATE business_subscriptions SET status=\'active\',published_at=COALESCE(published_at,NOW()),starts_at=COALESCE(starts_at,NOW()) WHERE business_id=? AND plan_code=\'free\' AND status=\'pending_publication\'');$out=[];
foreach($rows as $r){$name=$r['business']['name'];$find->execute([$r['destination_slug'],$name]);$existing=$find->fetchAll();if(count($existing)>0){$out[]=['destination'=>$r['destination_slug'],'name'=>$name,'status'=>'existing_not_modified'];continue;}
 try{BusinessPublicImporter::import($p,['schema_version'=>'business-import-v1','destination_slug'=>$r['destination_slug'],'businesses'=>[$r['business']]]);$find->execute([$r['destination_slug'],$name]);$found=$find->fetchAll();if(count($found)!==1)throw new RuntimeException('Import identity mismatch');$id=$found[0]['id'];$p->beginTransaction();$pub->execute([$id]);$sub->execute([$id]);$p->commit();$out[]=['destination'=>$r['destination_slug'],'name'=>$name,'id'=>$id,'status'=>'published_dev1','evidence_kind'=>$r['evidence_kind']];}
 catch(Throwable $e){if($p->inTransaction())$p->rollBack();$out[]=['destination'=>$r['destination_slug'],'name'=>$name,'status'=>'error','error'=>$e->getMessage()];}}
echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);
